#/**********************************************************************************************************************
# *	USER SPECIFIC SECTION:
# *	Change here AUTOSAR Project specific settings
# *********************************************************************************************************************/

# !! Change file paths here !!
rte_hook = "./ApplHw/GenData/Rte_Hook.h"              # Generated by RTE
rte_cmm  = "./ApplHw/Lauterbach/rte_runnable.cmm"      # Generated by this Script

# !! Change VFB hook prefix filters here !!
and_keywords = ['FUNC','void','RTE_APPL_CODE']
or_keywords  = ['Rte_Runnable_','SchM_Schedulable_']
components_keywords = ['EcuM_','ComM_','BswM_','Dcm_','Can_','Fee_','NvM_','Rtm_','Xcp_']

# *********************************************************************************************************************/

# -- Process files --

import os

# check if Rte_Hook.h is already processed
frtehookdst = open(rte_hook, 'r')
line = frtehookdst.readline()
while line:
    if "inline" in line:
        break
    line = frtehookdst.readline()
frtehookdst.close()
if line:
    print (rte_hook + " already processed. No action.")
    exit()

# rename Rte_Hook.h
rte_hook_src=rte_hook[0:rte_hook.rfind("/")]+"/Rte_Hook_Saved.h"
if os.path.exists(rte_hook_src):
    os.remove(rte_hook_src)
os.rename(rte_hook, rte_hook_src)

# open files
frtehooksrc = open(rte_hook_src, 'r')
frtehookdst = open(rte_hook, 'w')
frtecmm     = open(rte_cmm, 'w')

# grep the Function name
def GET_FuncName(str):
    sLoc=str.find(")")+1
    length=str[sLoc:].find("(")
    return ((str[sLoc:(sLoc+length)]).strip())

# grep the Runnables name, for example ")Runnables_name("
def GET_RunnableName(str):
    if or_keywords[0] in str:
        start=or_keywords[0]   #'Rte_Runnable_'
    elif or_keywords[1] in str:
        start=or_keywords[1]   #'SchM_Schedulable_'
    end='_Start('

    for component in components_keywords:
        if component in str:
            strnew = (str.split(start))[1].split(end)[0]
            strsplit = (strnew.split(component,1))
            str = start + strsplit[1] + end

    return ((str.split(start))[1].split(end)[0])

# print to file with newline
def File_Print(f,str):
    #print(str)
    f.write(str+'\n')

# process file

totalHook=1

line = frtehooksrc.readline()
while line:
    line=line.rstrip(); #remove the ^M (carriage return)
    if "Rte_Cfg.h" in line:
        # add includes and defines
        File_Print(frtehookdst, '# include "Std_Types.h"')
        File_Print(frtehookdst, '# include "arti.h"')
        File_Print(frtehookdst, '')
    if all(y in line for y in and_keywords):
        if any(x in line for x in or_keywords):
            if ("_Start(" in line):
                last_semi=line.rfind(";")
                line = "inline "+line[:last_semi]+" {"+line[last_semi+1:] #replace ";" -> "{"
                funcName=GET_FuncName(line)
                File_Print(frtehookdst, line)
                File_Print(frtehookdst, "	/* #ID "+funcName+" "+str(totalHook)+" */")
                File_Print(frtehookdst, "\tARTI_TRACE(USER, AR_CP_RTE_RUNNABLE, ct, 0, RteRunnable_Start, "+str(totalHook)+"); }") # "ct" just as dummy
                frtecmm.write("TASK.CREATE.RUNNABLE , "+str(totalHook)+". "+'\"'+GET_RunnableName(funcName+"(")+'\"'+'\n')
                totalHook=totalHook+1
            elif ("_Return(" in line):
                last_semi=line.rfind(";")
                line = "inline "+line[:last_semi]+" {"+line[last_semi+1:] #replace ";" -> "{"
                funcName=GET_FuncName(line)
                File_Print(frtehookdst, line)
                File_Print(frtehookdst, "\tARTI_TRACE(USER, AR_CP_RTE_RUNNABLE, ct, 0, RteRunnable_Return, "+str(totalHook)+"); }") # "ct" just as dummy
                totalHook=totalHook
            else:
                File_Print(frtehookdst, line)
            #print(line)
        else:
            File_Print(frtehookdst, line)
    else:
        File_Print(frtehookdst, line)
    line = frtehooksrc.readline()

print('\nfile: "{0}" and generated hooks number: {1}.\n'.format(frtehookdst.name, totalHook*2))

frtehooksrc.close()
frtehookdst.close()
frtecmm.close()

